// src/server/trafico-estado.ts
var CACHE_KEY5 = "trafico:valencia-estado:v1";
var TTL_MS5 = 3 * 60 * 1e3;
setLoadedDistricts(distritosFromGeoJSON(distritos_valencia_default));
async function handler5() {
  try {
    const { value: tramos, fresh } = await getOrFetch(
      CACHE_KEY5,
      TTL_MS5,
      () => fetchEstadoTrafico((lat, lon) => getDistrictAtCoordinates(lat, lon)?.codigo ?? null)
    );
    return new Response(JSON.stringify({ tramos, fresh }), {
      status: 200,
      headers: {
        "content-type": "application/json; charset=utf-8",
        "cache-control": "public, max-age=60, stale-while-revalidate=180"
      }
    });
  } catch (err) {
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 502, headers: { "content-type": "application/json; charset=utf-8" } }
    );
  }
}

// src/services/trafico-historico.ts
function mediaCongestion(distritos2) {
  const valores = distritos2.map((d2) => d2.congestion ?? d2.congestionMedia ?? 0);
  if (valores.length === 0) return 0;
  return valores.reduce((a2, b2) => a2 + b2, 0) / valores.length;
}
function construirHistoricoDistrito(snapshots, rollups, distritoCodigo, dias, ahora) {
  const desde = new Date(ahora.getTime() - dias * 24 * 60 * 60 * 1e3);
  const puntosHorarios = snapshots.filter((s) => new Date(s.timestamp) >= desde).map((s) => ({
    timestamp: s.timestamp,
    congestion: distritoCodigo ? s.distritos.find((d2) => d2.codigo === distritoCodigo)?.congestion ?? 0 : mediaCongestion(s.distritos),
    resolucion: "horaria"
  }));
  const puntosDiarios = rollups.filter((r) => /* @__PURE__ */ new Date(`${r.fecha}T00:00:00.000Z`) >= desde).map((r) => ({
    timestamp: `${r.fecha}T00:00:00.000Z`,
    congestion: distritoCodigo ? r.distritos.find((d2) => d2.codigo === distritoCodigo)?.congestionMedia ?? 0 : mediaCongestion(r.distritos),
    resolucion: "diaria"
  }));
  return [...puntosDiarios, ...puntosHorarios].sort((a2, b2) => a2.timestamp.localeCompare(b2.timestamp));
}

