// src/server/trafico-historico.ts
var DIAS_DEFECTO = 7;
var DIAS_MAXIMO = 400;
async function handler6(req) {
  const url2 = new URL(req.url);
  const distritoParam = url2.searchParams.get("distrito");
  const diasParam = Number(url2.searchParams.get("dias"));
  const dias = Number.isFinite(diasParam) && diasParam > 0 ? Math.min(diasParam, DIAS_MAXIMO) : DIAS_DEFECTO;
  const puntos = construirHistoricoDistrito(
    trafico_historico_default,
    trafico_historico_diario_default,
    distritoParam,
    dias,
    /* @__PURE__ */ new Date()
  );
  const historico = {
    distritoCodigo: distritoParam ?? "ciudad",
    puntos,
    fetchedAt: (/* @__PURE__ */ new Date()).toISOString(),
    source: "vlc-monitor-historico"
  };
  return new Response(JSON.stringify({ historico }), {
    status: 200,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "public, max-age=300, stale-while-revalidate=3600"
    }
  });
}

// src/services/valenbisi.ts
var GEOPORTAL_VALENBISI_URL = "https://geoportal.valencia.es/server/rest/services/OPENDATA/Trafico/MapServer/228/query?where=1=1&outFields=*&f=geojson";
async function fetchEstacionesValenbisi(resolverDistrito2) {
  const res = await fetch(GEOPORTAL_VALENBISI_URL, {
    headers: { "User-Agent": "vlc-monitor/1.0 (+https://github.com/)" }
  });
  if (!res.ok) {
    throw new Error(`Geoportal (Valenbisi) respondi\xF3 HTTP ${res.status}`);
  }
  const body = await res.json();
  if (!Array.isArray(body.features)) {
    throw new Error('Geoportal (Valenbisi) respondi\xF3 sin "features" \u2014 posible incidencia del servicio');
  }
  const fetchedAt = (/* @__PURE__ */ new Date()).toISOString();
  const featuresValidas = body.features.filter(
    (f) => f.geometry !== null && f.properties.gid !== null && f.properties.name !== null && f.properties.number !== null && f.properties.address !== null && f.properties.open !== null && f.properties.available !== null && f.properties.free !== null && f.properties.total !== null
  );
  return featuresValidas.map((feature) => {
    const [lon, lat] = feature.geometry.coordinates;
    return {
      id: String(feature.properties.gid),
      numero: feature.properties.number,
      nombre: feature.properties.name,
      direccion: feature.properties.address,
      lat,
      lon,
      abierta: feature.properties.open === "T",
      bicisDisponibles: feature.properties.available,
      huecosLibres: feature.properties.free,
      capacidadTotal: feature.properties.total,
      distrito: resolverDistrito2(lat, lon),
      observedAt: feature.properties.update_jcd ? new Date(feature.properties.update_jcd).toISOString() : fetchedAt,
      fetchedAt,
      source: "ajuntament-valencia-geoportal"
    };
  });
}

// src/server/valenbisi-estaciones.ts
var CACHE_KEY6 = "valenbisi:valencia-estaciones:v1";
var TTL_MS6 = 2 * 60 * 1e3;
setLoadedDistricts(distritosFromGeoJSON(distritos_valencia_default));
async function handler7() {
  try {
    const { value: estaciones, fresh } = await getOrFetch(
      CACHE_KEY6,
      TTL_MS6,
      () => fetchEstacionesValenbisi((lat, lon) => getDistrictAtCoordinates(lat, lon)?.codigo ?? null)
    );
    return new Response(JSON.stringify({ estaciones, fresh }), {
      status: 200,
      headers: {
        "content-type": "application/json; charset=utf-8",
        "cache-control": "public, max-age=60, stale-while-revalidate=120"
      }
    });
  } catch (err) {
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 502, headers: { "content-type": "application/json; charset=utf-8" } }
    );
  }
}

// src/services/aparcamiento.ts
var GEOPORTAL_PARKINGS_URL = "https://geoportal.valencia.es/server/rest/services/OPENDATA/Trafico/MapServer/194/query?where=1=1&outFields=*&f=geojson";
async function fetchAparcamientos(resolverDistrito2) {
  const res = await fetch(GEOPORTAL_PARKINGS_URL, {
    headers: { "User-Agent": "vlc-monitor/1.0 (+https://github.com/)" }
  });
  if (!res.ok) {
    throw new Error(`Geoportal (aparcamiento) respondi\xF3 HTTP ${res.status}`);
  }
  const body = await res.json();
  if (!Array.isArray(body.features)) {
    throw new Error('Geoportal (aparcamiento) respondi\xF3 sin "features" \u2014 posible incidencia del servicio');
  }
  const fetchedAt = (/* @__PURE__ */ new Date()).toISOString();
  const featuresValidas = body.features.filter(
    (f) => f.geometry !== null && f.properties.id_aparcamiento !== null && f.properties.nombre !== null && f.properties.direccion !== null && f.properties.plazastota !== null && f.properties.plazaslibr !== null && f.properties.ocupacion !== null
  );
  return featuresValidas.map((feature) => {
    const [lon, lat] = feature.geometry.coordinates;
    return {
      id: String(feature.properties.id_aparcamiento),
      nombre: feature.properties.nombre,
      direccion: feature.properties.direccion,
      lat,
      lon,
      plazasTotales: feature.properties.plazastota,
      plazasLibres: feature.properties.plazaslibr,
      ocupacionPorcentaje: feature.properties.ocupacion,
      sinDatos: feature.properties.plazaslibr < 0 || feature.properties.ocupacion < 0,
      distrito: resolverDistrito2(lat, lon),
      observedAt: feature.properties.ultima_mod ? new Date(feature.properties.ultima_mod).toISOString() : fetchedAt,
      fetchedAt,
      source: "ajuntament-valencia-geoportal"
    };
  });
}

